package org.lwjgl.sdl;

import org.lwjgl.glfw.GLFW;
import org.lwjgl.system.SharedLibrary;

/**
 * The SDL3 library handle. There is no SDL library on iOS: the layer in {@link SDLShim} stands in for it, so
 * the launcher's own native library is reported as "the SDL library". Minecraft only checks that it is not null.
 */
public final class SDL {

    private SDL() {}

    public static SharedLibrary getLibrary() {
        return GLFW.getLibrary();
    }

}
